jsonTools.init:
function init(eli) {
  function _toast(msg, type) { if (typeof showToast === "function") showToast(msg, type || "info"); }
  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }
  function _escHtmlBody(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
  }
  function _escXml(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&apos;");
  }

  // ─── Insert methods ──────────────────────────────────────────────
  // Each takes a string + run inside a Word.run, replacing the current
  // selection with the converted content. Returns a label + status.

  function _m_plainText(s) {
    return eli.host.runRaw("inserter_lab:plain", function (ctx) {
      var sel = ctx.document.getSelection();
      sel.insertText(s.replace(/\r?\n/g, ""), "Replace");
      return ctx.sync().then(function () { return "Inserted as plain text (newlines stripped)"; });
    });
  }

  function _m_keepNewlines(s) {
    return eli.host.runRaw("inserter_lab:keep_newlines", function (ctx) {
      var sel = ctx.document.getSelection();
      sel.insertText(s, "Replace");
      return ctx.sync().then(function () { return "Inserted as plain text (newlines preserved — Word renders \\n as vertical tab)"; });
    });
  }

  function _m_insertParagraph(s) {
    return eli.host.runRaw("inserter_lab:insertParagraph", function (ctx) {
      var lines = s.split(/\r?\n/).filter(function (l) { return l.trim().length > 0; });
      if (!lines.length) return ctx.sync().then(function () { return "Empty input"; });
      var sel = ctx.document.getSelection();
      var cur = sel.insertText(lines[0], "Replace");
      for (var i = 1; i < lines.length; i++) {
        cur = cur.insertParagraph(lines[i], "After");
      }
      return ctx.sync().then(function () { return "insertText first line + insertParagraph chain for " + lines.length + " lines"; });
    });
  }

  function _m_insertHtmlBr(s) {
    return eli.host.runRaw("inserter_lab:insertHtml_br", function (ctx) {
      var html = s.split(/\r?\n/).map(_escHtmlBody).join("<br>");
      ctx.document.getSelection().insertHtml(html, "Replace");
      return ctx.sync().then(function () { return "insertHtml with <br> soft line breaks (single paragraph)"; });
    });
  }

  function _m_insertHtmlP(s) {
    return eli.host.runRaw("inserter_lab:insertHtml_p", function (ctx) {
      var html = s.split(/\r?\n/)
        .filter(function (l) { return l.trim().length > 0; })
        .map(function (l) { return "<p>" + _escHtmlBody(l) + "</p>"; })
        .join("");
      ctx.document.getSelection().insertHtml(html, "Replace");
      return ctx.sync().then(function () { return "insertHtml with <p> per line (real paragraphs)"; });
    });
  }

  function _m_insertHtmlUl(s) {
    return eli.host.runRaw("inserter_lab:insertHtml_ul", function (ctx) {
      // Naive: every non-empty line becomes a <li>. Strip leading
      // `- ` / `* ` so they don't double-up with the auto-marker.
      var items = s.split(/\r?\n/)
        .map(function (l) { return l.trim().replace(/^[\-\*•]\s+/, ""); })
        .filter(function (l) { return l.length > 0; });
      if (!items.length) return ctx.sync().then(function () { return "Empty input"; });
      var html = "<ul>" + items.map(function (li) {
        return "<li>" + _escHtmlBody(li) + "</li>";
      }).join("") + "</ul>";
      ctx.document.getSelection().insertHtml(html, "Replace");
      return ctx.sync().then(function () { return "insertHtml with <ul><li> (Word converts to bulleted list)"; });
    });
  }

  function _m_insertHtmlOl(s) {
    return eli.host.runRaw("inserter_lab:insertHtml_ol", function (ctx) {
      var items = s.split(/\r?\n/)
        .map(function (l) { return l.trim().replace(/^(?:\d+|[a-z])[\.\)]\s+/i, ""); })
        .filter(function (l) { return l.length > 0; });
      if (!items.length) return ctx.sync().then(function () { return "Empty input"; });
      var html = "<ol>" + items.map(function (li) {
        return "<li>" + _escHtmlBody(li) + "</li>";
      }).join("") + "</ol>";
      ctx.document.getSelection().insertHtml(html, "Replace");
      return ctx.sync().then(function () { return "insertHtml with <ol><li> (Word converts to numbered list)"; });
    });
  }

  function _m_insertOoxmlParagraphs(s) {
    return eli.host.runRaw("inserter_lab:insertOoxml_p", function (ctx) {
      var lines = s.split(/\r?\n/).filter(function (l) { return l.trim().length > 0; });
      if (!lines.length) return ctx.sync().then(function () { return "Empty input"; });
      var paragraphs = lines.map(function (l) {
        return '<w:p><w:r><w:t xml:space="preserve">' + _escXml(l) + '</w:t></w:r></w:p>';
      }).join("");
      var pkg =
        '<?xml version="1.0" encoding="utf-8" standalone="yes"?>' +
        '<pkg:package xmlns:pkg="http://schemas.microsoft.com/office/2006/xmlPackage">' +
          '<pkg:part pkg:name="/_rels/.rels" pkg:contentType="application/vnd.openxmlformats-package.relationships+xml">' +
            '<pkg:xmlData>' +
              '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">' +
                '<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/>' +
              '</Relationships>' +
            '</pkg:xmlData>' +
          '</pkg:part>' +
          '<pkg:part pkg:name="/word/document.xml" pkg:contentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml">' +
            '<pkg:xmlData>' +
              '<w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">' +
                '<w:body>' + paragraphs + '</w:body>' +
              '</w:document>' +
            '</pkg:xmlData>' +
          '</pkg:part>' +
        '</pkg:package>';
      ctx.document.getSelection().insertOoxml(pkg, "Replace");
      return ctx.sync().then(function () { return "insertOoxml with raw <w:p> paragraphs (no styling, no list)"; });
    });
  }

  function _m_insertOoxmlBullets(s) {
    return eli.host.runRaw("inserter_lab:insertOoxml_bullets", function (ctx) {
      var lines = s.split(/\r?\n/)
        .map(function (l) { return l.trim().replace(/^[\-\*•]\s+/, ""); })
        .filter(function (l) { return l.length > 0; });
      if (!lines.length) return ctx.sync().then(function () { return "Empty input"; });
      // Define an abstractNum (multilevel bullet list) + numId, then each
      // paragraph references it. numId arbitrary high to avoid colliding
      // with target doc's existing numIds.
      var ABSID = "9001", NUMID = "9001";
      var numberingPart =
        '<pkg:part pkg:name="/word/numbering.xml" pkg:contentType="application/vnd.openxmlformats-officedocument.wordprocessingml.numbering+xml">' +
          '<pkg:xmlData>' +
            '<w:numbering xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">' +
              '<w:abstractNum w:abstractNumId="' + ABSID + '">' +
                '<w:lvl w:ilvl="0">' +
                  '<w:start w:val="1"/>' +
                  '<w:numFmt w:val="bullet"/>' +
                  '<w:lvlText w:val="•"/>' +
                  '<w:lvlJc w:val="left"/>' +
                  '<w:pPr><w:ind w:left="720" w:hanging="360"/></w:pPr>' +
                '</w:lvl>' +
              '</w:abstractNum>' +
              '<w:num w:numId="' + NUMID + '"><w:abstractNumId w:val="' + ABSID + '"/></w:num>' +
            '</w:numbering>' +
          '</pkg:xmlData>' +
        '</pkg:part>';
      var paragraphs = lines.map(function (l) {
        return '<w:p>' +
          '<w:pPr><w:numPr><w:ilvl w:val="0"/><w:numId w:val="' + NUMID + '"/></w:numPr></w:pPr>' +
          '<w:r><w:t xml:space="preserve">' + _escXml(l) + '</w:t></w:r>' +
          '</w:p>';
      }).join("");
      var rels =
        '<pkg:part pkg:name="/_rels/.rels" pkg:contentType="application/vnd.openxmlformats-package.relationships+xml">' +
          '<pkg:xmlData>' +
            '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">' +
              '<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/>' +
            '</Relationships>' +
          '</pkg:xmlData>' +
        '</pkg:part>';
      var docRels =
        '<pkg:part pkg:name="/word/_rels/document.xml.rels" pkg:contentType="application/vnd.openxmlformats-package.relationships+xml">' +
          '<pkg:xmlData>' +
            '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">' +
              '<Relationship Id="rId2" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/numbering" Target="numbering.xml"/>' +
            '</Relationships>' +
          '</pkg:xmlData>' +
        '</pkg:part>';
      var docPart =
        '<pkg:part pkg:name="/word/document.xml" pkg:contentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml">' +
          '<pkg:xmlData>' +
            '<w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">' +
              '<w:body>' + paragraphs + '</w:body>' +
            '</w:document>' +
          '</pkg:xmlData>' +
        '</pkg:part>';
      var pkg =
        '<?xml version="1.0" encoding="utf-8" standalone="yes"?>' +
        '<pkg:package xmlns:pkg="http://schemas.microsoft.com/office/2006/xmlPackage">' +
          rels + docRels + numberingPart + docPart +
        '</pkg:package>';
      ctx.document.getSelection().insertOoxml(pkg, "Replace");
      return ctx.sync().then(function () { return "insertOoxml with full numbering definition + bullet paragraphs"; });
    });
  }

  function _m_attachToList(s) {
    return eli.host.runRaw("inserter_lab:attachToList", function (ctx) {
      var lines = s.split(/\r?\n/)
        .map(function (l) { return l.trim().replace(/^[\-\*•]\s+/, ""); })
        .filter(function (l) { return l.length > 0; });
      if (!lines.length) return ctx.sync().then(function () { return "Empty input"; });
      // Phase 1: insert text + paragraphs (no list yet)
      var sel = ctx.document.getSelection();
      var firstP = sel.insertText(lines[0], "Replace").paragraphs.getFirst();
      var newParas = [firstP];
      for (var i = 1; i < lines.length; i++) {
        // Insert new paragraph after the previous one
        newParas.push(newParas[i - 1].insertParagraph(lines[i], "After"));
      }
      newParas.forEach(function (p) { p.load("uniqueLocalId"); });
      return ctx.sync().then(function () {
        // Phase 2: start a list on the first paragraph, attach the rest.
        try {
          var list = newParas[0].startNewList();
          list.load("id");
          return ctx.sync().then(function () {
            for (var j = 1; j < newParas.length; j++) {
              newParas[j].attachToList(list.id, 0);
            }
            return ctx.sync().then(function () {
              return "insertText + paragraph.startNewList + attachToList for " + newParas.length + " paragraphs";
            });
          });
        } catch (err) {
          return "Phase 2 attachToList failed: " + (err && err.message || "unknown");
        }
      });
    });
  }

  var METHODS = [
    { id: "plain",       label: "1. insertText (strip \\n)",    fn: _m_plainText,           desc: "Baseline. Newlines removed → one line." },
    { id: "keep_nl",     label: "2. insertText (keep \\n)",     fn: _m_keepNewlines,        desc: "Pass \\n through as-is. Word usually renders as vertical-tab character." },
    { id: "ins_para",    label: "3. insertParagraph chain",     fn: _m_insertParagraph,     desc: "First line via insertText, subsequent lines via range.insertParagraph(...,\"After\"). Each new line is its own paragraph, inheriting parent style." },
    { id: "html_br",     label: "4. insertHtml <br>",           fn: _m_insertHtmlBr,        desc: "Soft line breaks within ONE paragraph. No autoformat trigger. Markers stay literal." },
    { id: "html_p",      label: "5. insertHtml <p>",            fn: _m_insertHtmlP,         desc: "Each line a real <p> paragraph. Word may split parent paragraph." },
    { id: "html_ul",     label: "6. insertHtml <ul><li>",       fn: _m_insertHtmlUl,        desc: "Bulleted list. Strips leading `- `/`* `. Word converts to real bullets but may inherit parent indent." },
    { id: "html_ol",     label: "7. insertHtml <ol><li>",       fn: _m_insertHtmlOl,        desc: "Numbered list. Strips leading `1. `. Word converts to real numbering." },
    { id: "ooxml_p",     label: "8. insertOoxml <w:p>",         fn: _m_insertOoxmlParagraphs, desc: "Raw OOXML paragraphs, no styling. Direct control, no Word interpretation." },
    { id: "ooxml_bul",   label: "9. insertOoxml + numbering",   fn: _m_insertOoxmlBullets,  desc: "OOXML with full numbering.xml definition. Each paragraph references explicit numId. Should bypass autoformat entirely." },
    { id: "attach_list", label: "10. insertText + attachToList", fn: _m_attachToList,        desc: "Insert plain text + paragraph.startNewList() + attachToList. Programmatic Word list creation, no HTML/OOXML." },
  ];

  // ─── UI ──────────────────────────────────────────────────────────
  function _render() {
    var mount = document.getElementById("_eli3_dashboard_root");
    if (!mount) { _toast("Dashboard root missing", "err"); return; }
    mount.innerHTML = "";
    var root = document.createElement("div");
    root.style.cssText = "background:#f1f5f9;min-height:100%;padding:0;font:500 13px/1.45 'Inter','Segoe UI',sans-serif;color:#0f172a;";
    var defaultSample =
      "- First bullet item\n" +
      "- Second bullet item\n" +
      "- Third bullet item";

    var methodButtonsHtml = METHODS.map(function (m) {
      return '<div style="background:#fff;border:1px solid #e2e8f0;border-radius:8px;padding:10px 12px;margin-bottom:8px;">' +
        '<div style="display:flex;justify-content:space-between;align-items:center;gap:10px;">' +
          '<button data-method="' + _esc(m.id) + '" style="' +
            'flex:0 0 auto;padding:7px 14px;border:1px solid #1d4ed8;' +
            'background:linear-gradient(180deg,#3b82f6,#2563eb);color:#fff;' +
            'border-radius:5px;cursor:pointer;font:600 12px/1 \'Inter\',sans-serif;">' +
            '▶ ' + _esc(m.label) +
          '</button>' +
          '<div style="flex:1 1 auto;font:500 11px/1.4 \'Inter\',sans-serif;color:#475569;text-align:right;">' + _esc(m.desc) + '</div>' +
        '</div>' +
        '</div>';
    }).join("");

    root.innerHTML =
      '<div style="background:linear-gradient(180deg,#fff,#f8fafc);border-bottom:1px solid #e2e8f0;padding:14px 20px;display:flex;align-items:center;gap:12px;position:sticky;top:0;z-index:5;">' +
        '<button data-act="back" style="border:1px solid #e2e8f0;background:#fff;border-radius:6px;padding:4px 10px;cursor:pointer;font-size:14px;color:#475569;">←</button>' +
        '<div style="font:700 15px/1 \'Inter\',sans-serif;color:#0f172a;">🧪 Inserter Lab</div>' +
        '<div style="margin-left:auto;font-size:11px;color:#64748b;">admin-only · compare Word insert APIs</div>' +
      '</div>' +
      '<div style="padding:18px 22px;max-width:900px;margin:0 auto;">' +
        '<div style="background:#fef3c7;border:1px solid #f59e0b;border-radius:6px;padding:10px 12px;margin-bottom:14px;font:500 12px/1.5 \'Inter\',sans-serif;color:#78350f;">' +
          '<b>How to use:</b> Put your cursor in Word where you want to insert. Type/paste sample input below. Click each method button to compare results. ' +
          'For best testing, work on an empty paragraph or one that contains placeholder text you can select.' +
        '</div>' +
        '<label style="display:block;font:700 11px/1.3 \'Inter\',sans-serif;color:#64748b;letter-spacing:0.4px;text-transform:uppercase;margin-bottom:5px;">INPUT</label>' +
        '<textarea id="_eli3_inserter_input" style="width:100%;min-height:130px;border:1px solid #cbd5e1;border-radius:6px;padding:10px 12px;font:13px/1.5 ui-monospace,Menlo,monospace;background:#fff;box-sizing:border-box;resize:vertical;">' + _esc(defaultSample) + '</textarea>' +
        '<div style="margin-top:14px;">' + methodButtonsHtml + '</div>' +
        '<div id="_eli3_inserter_status" style="margin-top:14px;padding:10px 12px;background:#fff;border:1px solid #e2e8f0;border-radius:6px;font:500 12px/1.5 \'Inter\',sans-serif;color:#475569;min-height:22px;">Status will appear here.</div>' +
      '</div>';

    mount.appendChild(root);

    root.querySelector("[data-act='back']").onclick = function () {
      if (eli.dashboard && eli.dashboard.goHome) eli.dashboard.goHome();
    };
    var inputEl = root.querySelector("#_eli3_inserter_input");
    var statusEl = root.querySelector("#_eli3_inserter_status");
    root.querySelectorAll("[data-method]").forEach(function (btn) {
      btn.onclick = function () {
        var id = btn.getAttribute("data-method");
        var m = METHODS.filter(function (x) { return x.id === id; })[0];
        if (!m) return;
        var val = inputEl.value;
        if (!val.trim()) { statusEl.innerHTML = '<span style="color:#b91c1c;">Empty input.</span>'; return; }
        statusEl.innerHTML = '<span style="color:#475569;">⏳ Running ' + _esc(m.label) + '…</span>';
        m.fn(val)
          .then(function (msg) {
            statusEl.innerHTML = '<span style="color:#047857;">✅ ' + _esc(msg || "Done") + '</span>';
            try { console.log("[inserter_lab] " + m.id + " OK:", msg); } catch (_) {}
          })
          .catch(function (err) {
            var msg = (err && err.message) || String(err);
            statusEl.innerHTML = '<span style="color:#b91c1c;">❌ ' + _esc(msg) + '</span>';
            try { console.error("[inserter_lab] " + m.id + " FAILED:", err); } catch (_) {}
          });
      };
    });
  }

  eli.register({
    tile: { app_inserter_lab: _render },
    inserter_lab: { open: _render },
  });

  eli.log.event("tool", "inserter_lab_initialized", {});
}
